function archetypeFor(f){
  const n=f.name.toLowerCase();
  if(/manta|ray|skate/.test(n)) return 'ray';
  if(/eel|moray|pipefish/.test(n)) return 'eel';
  if(/shark|barracuda|swordfish|marlin|swordfin/.test(n)) return 'predator';
  if(/crab|lobster|shrimp/.test(n)) return 'crustacean';
  if(/squid|jelly/.test(n)) return /jelly/.test(n)?'jelly':'squid';
  if(/seahorse/.test(n)) return 'seahorse';
  if(/puffer/.test(n)) return 'puffer';
  if(/tuna|sturgeon|grouper/.test(n)) return 'heavy';
  if(/minnow|sardine|sprat|herring|tetra|chromis|goby/.test(n)) return 'school';
  return 'fish';
}
function behaviorFor(f){
  if(f.rarity==='mythic'||f.temperament==='boss') return 'legendary';
  const a=archetypeFor(f);
  if(a==='predator'||f.temperament==='aggressive') return 'predator';
  if(a==='crustacean') return 'bottom';
  if(a==='eel'&&['kelp','shipgrave','morytania'].includes(f.biome)) return 'ambush';
  if(a==='school'||f.temperament==='school') return 'school';
  if(f.temperament==='territorial') return 'territorial';
  if(f.temperament==='curious') return 'curious';
  if(f.temperament==='flee') return 'nervous';
  if(f.rarity==='epic'||f.rarity==='legendary') return 'darting';
  return 'wander';
}
for(const f of FISH){
  const rank=RARITY[f.rarity]?.rank||1;
  const local=(f.sort-1)%12;
  f.archetype=archetypeFor(f);
  f.behavior=behaviorFor(f);
  f.depth_min=Math.max(0,Math.min(.82,(rank-1)*.12+(local%3)*.025));
  f.depth_max=Math.min(.98,.48+rank*.085+(local%4)*.035);
  if(f.behavior==='bottom'){f.depth_min=Math.max(.58,f.depth_min);f.depth_max=.98;}
  if(f.behavior==='ambush'){f.depth_min=Math.max(.38,f.depth_min);}
  if(f.behavior==='legendary'){f.depth_min=.72;f.depth_max=.99;}
  f.weight_min=+(f.weight*(f.rarity==='mythic'?.9:.76)).toFixed(2);
  f.weight_max=+(f.weight*(f.rarity==='mythic'?1.55:1.34)).toFixed(2);
  f.threat=(f.behavior==='predator'||f.behavior==='legendary')?Math.min(5,rank):0;
}
